using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

namespace YourApp;

/// <summary>
/// Global exception handler that maps known exceptions to RFC 7807 Problem Details responses.
/// Register with: builder.Services.AddExceptionHandler<GlobalExceptionHandler>();
/// </summary>
public class GlobalExceptionHandler : IExceptionHandler
{
    private readonly ILogger<GlobalExceptionHandler> _logger;

    public GlobalExceptionHandler(ILogger<GlobalExceptionHandler> logger)
    {
        _logger = logger;
    }

    public async ValueTask<bool> TryHandleAsync(
        HttpContext httpContext,
        Exception exception,
        CancellationToken cancellationToken)
    {
        var (statusCode, title) = exception switch
        {
            KeyNotFoundException => (StatusCodes.Status404NotFound, "Resource Not Found"),
            ArgumentException => (StatusCodes.Status400BadRequest, "Bad Request"),
            InvalidOperationException => (StatusCodes.Status409Conflict, "Conflict"),
            _ => (StatusCodes.Status500InternalServerError, "Internal Server Error")
        };

        _logger.LogError(exception, "Unhandled exception: {Message}", exception.Message);

        var problemDetails = new ProblemDetails
        {
            Status = statusCode,
            Title = title,
            Type = $"https://httpstatuses.com/{statusCode}",
            // Only expose exception detail for non-500 errors
            Detail = statusCode != StatusCodes.Status500InternalServerError
                ? exception.Message
                : "An unexpected error occurred. Please try again later."
        };

        httpContext.Response.StatusCode = statusCode;
        await httpContext.Response.WriteAsJsonAsync(problemDetails, cancellationToken);

        return true; // Signal that the exception was handled
    }
}

// Add these to your Program.cs setup:

// ──── Service Registration ────
// builder.Services.AddProblemDetails();
// builder.Services.AddExceptionHandler<GlobalExceptionHandler>();

// ──── Middleware Pipeline (order matters — place early) ────
// app.UseExceptionHandler();    // activates IExceptionHandler
// app.UseStatusCodePages();     // converts empty error responses to ProblemDetails

// ──── Full minimal example ────

using YourApp;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddProblemDetails();                          // RFC 7807 support
builder.Services.AddExceptionHandler<GlobalExceptionHandler>(); // our custom handler

var app = builder.Build();

app.UseExceptionHandler();   // hooks IExceptionHandler into the pipeline
app.UseStatusCodePages();    // wraps non-exception 4xx/5xx in ProblemDetails too

// Sample endpoints to demonstrate behavior
app.MapGet("/items/{id}", (int id) =>
{
    if (id < 0) throw new ArgumentException("ID must be non-negative.");
    if (id == 0) throw new KeyNotFoundException("Item not found.");
    if (id == 999) throw new InvalidOperationException("Item is archived.");
    if (id == 13) throw new Exception("Something unexpected broke.");

    return Results.Ok(new { Id = id, Name = "Widget" });
});

app.Run();

